import express from "express";
import fs from "fs";
import path from "path";

const app = express();
const HLS_ROOT = path.join(__dirname, "media", "hls");

/**
 * Serves the master manifest for a video.
 * GET /hls/:videoId/master.m3u8
 */
app.get("/hls/:videoId/master.m3u8", (req, res) => {
  const { videoId } = req.params;
  const manifestPath = path.join(HLS_ROOT, videoId, "master.m3u8");

  if (!fs.existsSync(manifestPath)) {
    return res.status(404).send("Manifest not found");
  }

  const body = fs.readFileSync(manifestPath, "utf-8");

  res.setHeader("Content-Type", "application/vnd.apple.mpegurl");
  // CORS is explicitly enabled here, which is why the manifest loads fine in the browser.
  res.setHeader("Access-Control-Allow-Origin", "*");
  res.status(200).send(body);
});

/**
 * Serves a variant (quality-level) playlist for a video.
 * GET /hls/:videoId/:variant.m3u8
 */
app.get("/hls/:videoId/:variant.m3u8", (req, res) => {
  const { videoId, variant } = req.params;
  const variantPath = path.join(HLS_ROOT, videoId, `${variant}.m3u8`);

  if (!fs.existsSync(variantPath)) {
    return res.status(404).send("Variant playlist not found");
  }

  const body = fs.readFileSync(variantPath, "utf-8");

  res.setHeader("Content-Type", "application/vnd.apple.mpegurl");
  // No Access-Control-Allow-Origin header set here.
  res.status(200).send(body);
});

/**
 * Serves an individual .ts media segment for a video.
 * GET /hls/:videoId/:segment.ts
 */
app.get("/hls/:videoId/:segment.ts", (req, res) => {
  const { videoId, segment } = req.params;
  const segmentPath = path.join(HLS_ROOT, videoId, `${segment}.ts`);

  if (!fs.existsSync(segmentPath)) {
    return res.status(404).send("Segment not found");
  }

  res.setHeader("Content-Type", "video/mp2t");
  // No Access-Control-Allow-Origin header set here either.
  // The bytes, encoding, and status code are all correct -- curl against
  // this exact URL returns 200 with the right payload every time.
  fs.createReadStream(segmentPath).pipe(res);
});

app.listen(4000, () => {
  console.log("HLS origin server listening on http://cdn.example.com:4000");
});

